func (f roundTripFunc) RoundTrip(req *http.Request) (*http.Response, error) {
	return f(req)
}

func mustParseURL(t *testing.T, rawURL string) interface{ String() string } {
	t.Helper()
	import_net_url, _ := http.NewRequest(http.MethodGet, rawURL, nil) //nolint:errcheck
