package settings

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestLoad_RejectsUnknownKeys(t *testing.T) {
	// Create a temporary directory
	tmpDir := t.TempDir()

	// Create .entire directory
	entireDir := filepath.Join(tmpDir, ".entire")
	if err := os.MkdirAll(entireDir, 0755); err != nil {
		t.Fatalf("failed to create .entire directory: %v", err)
	}

	// Create settings.json with an unknown key
	settingsFile := filepath.Join(entireDir, "settings.json")
	settingsContent := `{"strategy": "manual-commit", "unknown_key": "value"}`
	if err := os.WriteFile(settingsFile, []byte(settingsContent), 0644); err != nil {
		t.Fatalf("failed to write settings file: %v", err)
	}

	// Initialize a git repo (required by paths.AbsPath)
	if err := os.MkdirAll(filepath.Join(tmpDir, ".git"), 0755); err != nil {
		t.Fatalf("failed to create .git directory: %v", err)
	}

	// Change to the temp directory
	t.Chdir(tmpDir)

	// Try to load settings - should fail due to unknown key
	_, err := Load()
	if err == nil {
		t.Error("expected error for unknown key, got nil")
	} else if !containsUnknownField(err.Error()) {
		t.Errorf("expected unknown field error, got: %v", err)
	}
}

func TestLoad_AcceptsValidKeys(t *testing.T) {
	// Create a temporary directory
	tmpDir := t.TempDir()

	// Create .entire directory
	entireDir := filepath.Join(tmpDir, ".entire")
	if err := os.MkdirAll(entireDir, 0755); err != nil {
		t.Fatalf("failed to create .entire directory: %v", err)
	}

	// Create settings.json with all valid keys
	settingsFile := filepath.Join(entireDir, "settings.json")
	settingsContent := `{
		"strategy": "auto-commit",
		"enabled": true,
		"local_dev": false,
		"log_level": "debug",
		"strategy_options": {"key": "value"},
		"telemetry": true
	}`
	if err := os.WriteFile(settingsFile, []byte(settingsContent), 0644); err != nil {
		t.Fatalf("failed to write settings file: %v", err)
	}

	// Initialize a git repo (required by paths.AbsPath)
	if err := os.MkdirAll(filepath.Join(tmpDir, ".git"), 0755); err != nil {
		t.Fatalf("failed to create .git directory: %v", err)
	}

	// Change to the temp directory
	t.Chdir(tmpDir)

	// Load settings - should succeed
	settings, err := Load()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	// Verify values
	if settings.Strategy != "auto-commit" {
		t.Errorf("expected strategy 'auto-commit', got %q", settings.Strategy)
	}
	if !settings.Enabled {
		t.Error("expected enabled to be true")
	}
	if settings.LogLevel != "debug" {
		t.Errorf("expected log_level 'debug', got %q", settings.LogLevel)
	}
	if settings.Telemetry == nil || !*settings.Telemetry {
		t.Error("expected telemetry to be true")
	}
}

func TestLoad_LocalSettingsRejectsUnknownKeys(t *testing.T) {
	// Create a temporary directory
	tmpDir := t.TempDir()

	// Create .entire directory
	entireDir := filepath.Join(tmpDir, ".entire")
	if err := os.MkdirAll(entireDir, 0755); err != nil {
		t.Fatalf("failed to create .entire directory: %v", err)
	}

	// Create valid settings.json
	settingsFile := filepath.Join(entireDir, "settings.json")
	settingsContent := `{"strategy": "manual-commit"}`
	if err := os.WriteFile(settingsFile, []byte(settingsContent), 0644); err != nil {
		t.Fatalf("failed to write settings file: %v", err)
	}

	// Create settings.local.json with an unknown key
	localSettingsFile := filepath.Join(entireDir, "settings.local.json")
	localSettingsContent := `{"bad_key": true}`
	if err := os.WriteFile(localSettingsFile, []byte(localSettingsContent), 0644); err != nil {
		t.Fatalf("failed to write local settings file: %v", err)
	}

	// Initialize a git repo (required by paths.AbsPath)
	if err := os.MkdirAll(filepath.Join(tmpDir, ".git"), 0755); err != nil {
		t.Fatalf("failed to create .git directory: %v", err)
	}

	// Change to the temp directory
	t.Chdir(tmpDir)

	// Try to load settings - should fail due to unknown key in local settings
	_, err := Load()
	if err == nil {
		t.Error("expected error for unknown key in local settings, got nil")
	} else if !containsUnknownField(err.Error()) {
		t.Errorf("expected unknown field error, got: %v", err)
	}
}

// containsUnknownField checks if the error message indicates an unknown field
func containsUnknownField(msg string) bool {
	// Go's json package reports unknown fields with this message format
	return strings.Contains(msg, "unknown field")
}

package summarize

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// openAITestGenerator returns an OpenAIGenerator wired to the given test server.
func openAITestGenerator(t *testing.T, srv *httptest.Server, apiKey string) *OpenAIGenerator {
	t.Helper()
	return &OpenAIGenerator{
		APIKey:   apiKey,
		endpoint: srv.URL,
	}
}

// openAISuccessHandler returns an HTTP handler that responds with a valid summary JSON.
func openAISuccessHandler(t *testing.T, intent, outcome string) http.HandlerFunc {
	t.Helper()
	return func(w http.ResponseWriter, _ *http.Request) {
		body, err := json.Marshal(map[string]any{
			"intent":     intent,
			"outcome":    outcome,
			"learnings":  map[string]any{"repo": []any{}, "code": []any{}, "workflow": []any{}},
			"friction":   []any{},
			"open_items": []any{},
		})
		if err != nil {
			t.Errorf("failed to marshal summary: %v", err)
		}
		resp := openAIResponse{Choices: []openAIChoice{{Message: openAIMessage{Content: string(body)}}}}
		w.Header().Set("Content-Type", "application/json")
		if encErr := json.NewEncoder(w).Encode(resp); encErr != nil {
			t.Errorf("failed to encode response: %v", encErr)
		}
	}
}

func TestOpenAIGenerator_MissingAPIKey(t *testing.T) {
	t.Parallel()
	t.Setenv("OPENAI_API_KEY", "")
	gen := &OpenAIGenerator{}
	input := Input{Transcript: []Entry{{Type: EntryTypeUser, Content: "Hello"}}}
	_, err := gen.Generate(context.Background(), input)
	if err == nil {
		t.Fatal("expected error for missing API key")
	}
	if !strings.Contains(err.Error(), "API key") {
		t.Errorf("expected API key error, got: %v", err)
	}
}

func TestOpenAIGenerator_EnvAPIKey(t *testing.T) {
	t.Parallel()
	srv := httptest.NewServer(openAISuccessHandler(t, "from env key", "ok"))
	defer srv.Close()

	t.Setenv("OPENAI_API_KEY", "sk-env-test")
	gen := &OpenAIGenerator{endpoint: srv.URL}

	input := Input{Transcript: []Entry{{Type: EntryTypeUser, Content: "Hello"}}}
	summary, err := gen.Generate(context.Background(), input)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if summary.Intent != "from env key" {
		t.Errorf("unexpected intent: %s", summary.Intent)
	}
}

func TestOpenAIGenerator_SuccessResponse(t *testing.T) {
	t.Parallel()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !strings.HasPrefix(r.Header.Get("Authorization"), "Bearer ") {
			http.Error(w, "missing auth", http.StatusUnauthorized)
			return
		}
		openAISuccessHandler(t, "test intent", "test outcome")(w, r)
	}))
	defer srv.Close()

	gen := openAITestGenerator(t, srv, "sk-test")
	input := Input{Transcript: []Entry{{Type: EntryTypeUser, Content: "Help me"}}}
	summary, err := gen.Generate(context.Background(), input)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if summary.Intent != "test intent" {
		t.Errorf("unexpected intent: %s", summary.Intent)
	}
	if summary.Outcome != "test outcome" {
		t.Errorf("unexpected outcome: %s", summary.Outcome)
	}
}

func TestOpenAIGenerator_APIError(t *testing.T) {
	t.Parallel()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusUnauthorized)
		resp := openAIResponse{Error: &openAIError{Message: "invalid API key", Type: "invalid_request_error"}}
		if encErr := json.NewEncoder(w).Encode(resp); encErr != nil {
			t.Errorf("failed to encode response: %v", encErr)
		}
	}))
	defer srv.Close()

	gen := openAITestGenerator(t, srv, "sk-bad")
	input := Input{Transcript: []Entry{{Type: EntryTypeUser, Content: "Hello"}}}
	_, err := gen.Generate(context.Background(), input)
	if err == nil {
		t.Fatal("expected error for API error response")
	}
	if !strings.Contains(err.Error(), "invalid API key") {
		t.Errorf("expected API error message, got: %v", err)
	}
}

func TestOpenAIGenerator_NoChoices(t *testing.T) {
	t.Parallel()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		resp := openAIResponse{Choices: []openAIChoice{}}
		w.Header().Set("Content-Type", "application/json")
		if encErr := json.NewEncoder(w).Encode(resp); encErr != nil {
			t.Errorf("failed to encode response: %v", encErr)
		}
	}))
